# typed: strict
# frozen_string_literal: true

# Generated by scripts/release/package_metadata.py. Do not edit.
class Devknx < Formula
  desc "KNX monitor with CLI, TUI, GUI, REST and MCP"
  homepage "https://github.com/metaneutrons/devknx"
  license "GPL-3.0-only"

  on_macos do
    depends_on arch: :arm64
    on_arm do
      url "https://github.com/metaneutrons/devknx/releases/download/v0.3.1/devknx-v0.3.1-aarch64-apple-darwin.tar.gz"
      sha256 "7d49ce17773ecef9b6c47182861e94dbce14cc0bdf52f61583d75c46c4bb3987"
    end
  end

  on_linux do
    depends_on "libx11"
    depends_on "libxcb"
    depends_on "libxcursor"
    depends_on "libxi"
    depends_on "libxkbcommon"
    depends_on "mesa"
    depends_on "wayland"
    if Hardware::CPU.arm?
      url "https://github.com/metaneutrons/devknx/releases/download/v0.3.1/devknx-v0.3.1-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "e88eb9b953b36e41ac1f66dfe2b0d3e7708eb32000a0fc68cd23c257ae497f08"
    else
      url "https://github.com/metaneutrons/devknx/releases/download/v0.3.1/devknx-v0.3.1-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "0bcba429a4fd498885cc30abe534813eb49c9b178401b92e21756cbc927ec815"
    end
  end

  def install
    root = Dir["devknx", "devknx-v*-*/devknx"].find { |path| File.file?(path) }
    raise "missing devknx executable" unless root

    if OS.linux?
      libexec.install root
      gui_libraries = %w[
        libx11 libxcb libxcursor libxi libxkbcommon mesa wayland
      ].map { |name| formula_opt_lib(name) }
      loader_path = "#{gui_libraries.join(":")}${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
      bin.join("devknx").write_env_script libexec/"devknx", LD_LIBRARY_PATH: loader_path
    else
      bin.install root
    end
    source_root = File.dirname(root)
    doc.install File.join(source_root, "THIRD-PARTY-NOTICES.md")
    doc.install File.join(source_root, "licenses")
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/devknx --version")
  end
end
